private void ShowTimeClick(object sender, RoutedEventArgs e)
{
	CloseTimeDialog();
	if (SelectedItemSource == null)
	{
		return;
	}
	object curDiagramAreaSource = CurDiagramAreaSource;
	if (curDiagramAreaSource is IVmModuleSet)
	{
		TimeDialog = new ShowTimeDialog();
		TimeDialog.DataContext = curDiagramAreaSource;
		TimeDialog.Owner = Application.Current?.MainWindow;
		if (AppLocalizationService.GetLang("Language") == "English")
		{
			TimeDialog.Width = 470.0;
		}
		TimeDialog.Show();
	}
}

