	public void CloseTimeDialog()
	{
		if (TimeDialog != null)
		{
			TimeDialog.Close();
			TimeDialog = null;
		}
	}
}

public double ZoomValueE
{
	get
	{
		if (ZoomIndex >= 0 && ZoomIndex <= ZoomTicksCount)
		{
			return _ZoomTicks[ZoomIndex] * 100.0;
		}
		return 1.0;
	}
}

public int ZoomTicksCount => _ZoomTicks.Count - 1;

private ShowTimeDialog TimeDialog { get; set; }

public event PropertyChangedEventHandler PropertyChanged;

public override void OnPropertyChanged(string name)
{
	base.OnPropertyChanged(name);
	if (name == "UnReadyModuleName" || name == "IsReady")
	{
		OnPropertyChanged("WorkState");
		OnPropertyChanged("WorkStateInfo");
	}
}
